import{_ as o,o as i,c as t,a5 as n}from"./chunks/framework.CsGesDJn.js";const u=JSON.parse('{"title":"3.3.3 View Client Profile","description":"","frontmatter":{},"headers":[],"relativePath":"feature/profile/3-3-3-view-client-profile/spec.md","filePath":"feature/profile/3-3-3-view-client-profile/spec.md"}'),a={name:"feature/profile/3-3-3-view-client-profile/spec.md"};function r(l,e,s,c,d,h){return i(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="_3-3-3-view-client-profile" tabindex="-1">3.3.3 View Client Profile <a class="header-anchor" href="#_3-3-3-view-client-profile" aria-label="Permalink to &quot;3.3.3 View Client Profile&quot;">​</a></h1><p>&gt; V2 (2026-10-02): ClientProfile reworked — owned by the User, independent of any Agency. See <a href="./plan.html">plan.md</a> §6 for the migration rationale.</p><h2 id="function-trigger" tabindex="-1">Function Trigger <a class="header-anchor" href="#function-trigger" aria-label="Permalink to &quot;Function Trigger&quot;">​</a></h2><p>Begins when a user opens their own list of Client Profiles (&quot;My Brand Profiles&quot;), or when an Agency Manager/Owner opens a workspace&#39;s Client list to manage collaborating clients.</p><h2 id="function-description" tabindex="-1">Function Description <a class="header-anchor" href="#function-description" aria-label="Permalink to &quot;Function Description&quot;">​</a></h2><ul><li><strong>Actors / Roles:</strong> Any signed-in user, viewing the Client Profiles they personally own; Agency members (Owner/Manager) when viewing a workspace&#39;s Client list (<code>/workspaces/{id}/clients</code>).</li><li><strong>Purpose:</strong> Let a user manage the Client Profiles they own — one person may represent several brands (e.g. Nike, Adidas) and hold one profile per brand, none of which belong to any Agency. A profile is reused across every workspace/Agency the user collaborates with, instead of re-entering brand details per Agency.</li><li><strong>Interface:</strong> The personal screen at <code>/client-profiles</code> lists every Client Profile the signed-in user owns — no Agency context required. A separate Workspace Client list, at <code>/workspaces/{id}/clients</code>, shows every <code>WorkspaceMember</code> with role CLIENT currently linked to that workspace (via <code>client_profile_id</code>), used by Agency Managers to manage who is collaborating and to invite new clients.</li><li><strong>Data Processing:</strong> The system resolves the caller&#39;s identity from the access token and returns every Client Profile where <code>userId</code> matches the caller. For the workspace list, the system returns the workspace&#39;s active CLIENT members joined with their linked Client Profile for display.</li></ul><h2 id="screen-layout" tabindex="-1">Screen Layout <a class="header-anchor" href="#screen-layout" aria-label="Permalink to &quot;Screen Layout&quot;">​</a></h2><p>Figure — My Brand Profiles (<code>/client-profiles</code>):</p><ul><li>Center: list of every Client Profile the signed-in user owns — display name, company, contact details, logo.</li><li>Buttons: Create new profile, Edit, Delete (blocked if the profile is linked to an active workspace membership).</li></ul><p>Figure — Workspace Client List (<code>/workspaces/{id}/clients</code>):</p><ul><li>Center: list of active CLIENT members of this workspace — display name (from the linked Client Profile), joined date, status.</li><li>Buttons: &quot;Add client&quot; (Owner/Manager only) — opens an invite-by-email dialog (see FR 3.4.7 for the invite flow and the auto-suggest behavior).</li></ul><h2 id="function-details" tabindex="-1">Function Details <a class="header-anchor" href="#function-details" aria-label="Permalink to &quot;Function Details&quot;">​</a></h2><h3 id="data-specifications" tabindex="-1">Data Specifications <a class="header-anchor" href="#data-specifications" aria-label="Permalink to &quot;Data Specifications&quot;">​</a></h3><ul><li><strong>Input required:</strong> None beyond the caller&#39;s identity (My Brand Profiles); the workspace identifier, for the Workspace Client list.</li><li><strong>Input optional:</strong> None.</li><li><strong>System data:</strong> <code>client_profiles</code> — <code>id</code>, <code>userId</code>, <code>displayName</code>, <code>company</code>, <code>phone</code>, <code>note</code>, <code>logoUrl</code>, <code>website</code>, <code>industry</code>, <code>location</code>, <code>description</code>, <code>socialLinks</code>, <code>contactName</code>, <code>contactEmail</code>, <code>companySize</code>, <code>instagramUrl</code>, <code>taxCode</code>, <code>address</code>, <code>tagline</code>, <code>foundedYear</code>, <code>budgetRange</code>, <code>createdAt</code>, <code>updatedAt</code>. <code>workspace_members</code> — the link between a Client Profile and a workspace is <code>client_profile_id</code> on <code>workspace_members</code>, not any field on <code>client_profiles</code> itself.</li><li><strong>Output:</strong> Every Client Profile owned by the caller, or the list of active CLIENT members for one workspace.</li></ul><h3 id="business-rules" tabindex="-1">Business Rules <a class="header-anchor" href="#business-rules" aria-label="Permalink to &quot;Business Rules&quot;">​</a></h3><ul><li><strong>BR-41 (reworked):</strong> A Client Profile belongs to exactly one User (<code>userId</code>) and is never scoped to an Agency. One user may hold several independent Client Profiles — one per brand/customer they represent (e.g. a marketing lead holding separate &quot;Nike&quot; and &quot;Adidas&quot; profiles) — completely unrelated to how many Agencies or workspaces they collaborate with.</li><li><strong>Implementation note (no dedicated global BR):</strong> The same Client Profile can be linked (via <code>workspace_members.client_profile_id</code>) to any number of workspaces across any number of Agencies simultaneously. Linking a profile to a second workspace of a different Agency does not create a new profile and does not affect the profile&#39;s data as seen from the first workspace.</li><li><strong>Implementation note (no dedicated global BR):</strong> A Client Profile is created either explicitly by its owner (on <code>/client-profiles</code>, see FR 3.3.4) or inline during a CLIENT invitation accept flow (see FR 3.4.7) — never implicitly, and never keyed by an Agency.</li><li><strong>BR-38:</strong> Client access is scoped by workspace membership — a client can only see/approve content in workspaces where their Client Profile is actively linked. A Client Profile is independent of the user&#39;s own User Profile (3.3.1) — one user may hold both at the same time, for example owning their own Agency while also being a CLIENT collaborator (via a Client Profile) in another Agency&#39;s workspace.</li></ul><h3 id="validation" tabindex="-1">Validation <a class="header-anchor" href="#validation" aria-label="Permalink to &quot;Validation&quot;">​</a></h3><ul><li>Missing, expired, or invalid access token → 401 <code>UNAUTHORIZED</code>, Display: MSG22.</li><li>Workspace Client list: missing or invalid workspace identifier → 404 <code>WORKSPACE_NOT_FOUND</code>.</li></ul><h2 id="functionalities" tabindex="-1">Functionalities <a class="header-anchor" href="#functionalities" aria-label="Permalink to &quot;Functionalities&quot;">​</a></h2><h3 id="normal-flow" tabindex="-1">Normal Flow <a class="header-anchor" href="#normal-flow" aria-label="Permalink to &quot;Normal Flow&quot;">​</a></h3><ol><li>The user opens &quot;My Brand Profiles&quot; (<code>/client-profiles</code>).</li><li>The system resolves the caller&#39;s identity from the access token.</li><li>The system returns every Client Profile where <code>userId</code> matches the caller.</li><li>The application renders the list — one card per brand the user represents.</li><li>Alternatively, an Agency Manager/Owner opens a workspace&#39;s Client list; the system returns that workspace&#39;s active CLIENT members (each resolved through <code>workspace_members.client_profile_id</code>), and the application displays them with an &quot;Add client&quot; action.</li></ol><h3 id="abnormal-cases" tabindex="-1">Abnormal Cases <a class="header-anchor" href="#abnormal-cases" aria-label="Permalink to &quot;Abnormal Cases&quot;">​</a></h3><ul><li>N.a1: Missing, expired, or invalid access token at any step → 401 <code>UNAUTHORIZED</code>, toast MSG22. N.a2: The user signs in again at <code>/login</code> (3.2.2).</li><li>5.a1: Invalid or missing workspace identifier → 404 <code>WORKSPACE_NOT_FOUND</code>. 5.a2: The application returns to the workspace list.</li></ul><h2 id="post-conditions" tabindex="-1">Post-Conditions <a class="header-anchor" href="#post-conditions" aria-label="Permalink to &quot;Post-Conditions&quot;">​</a></h2><ul><li>Every Client Profile owned by the caller is displayed with the values currently stored for it, independent of any Agency context.</li><li>The Workspace Client list reflects the workspace&#39;s current active CLIENT members only.</li><li>No data is changed; the operation is read-only.</li></ul>',25)])])}const f=o(a,[["render",r]]);export{u as __pageData,f as default};
